// ---- Query language ----
// operands: word | "phrase" | #tag ; operators: AND OR NOT + parentheses ;
// space between operands = implicit AND. AND/OR/NOT are operators only when
// unquoted; quote them ("and") to search the literal word.
function tokenize(q){
  const toks=[]; let i=0;
  while(i<q.length){
    const c=q[i];
    if(/\s/.test(c)){ i++; continue; }
    if(c==='('){ toks.push({t:'('}); i++; continue; }
    if(c===')'){ toks.push({t:')'}); i++; continue; }
    if(c==='"'){ let j=i+1,s=''; while(j<q.length&&q[j]!=='"'){ s+=q[j]; j++; }
      toks.push({t:'op',kind:'phrase',v:s}); i=(j<q.length)?j+1:j; continue; }
    // bare token: read until whitespace or parenthesis
    let j=i,s=''; while(j<q.length && !/[\s()]/.test(q[j])){ s+=q[j]; j++; } i=j;
    if(/^(and|or|not)$/i.test(s)){ toks.push({t:s.toLowerCase()}); continue; }
    if(s[0]==='#'){ toks.push({t:'op',kind:'tag',v:s.slice(1)}); continue; }
    toks.push({t:'op',kind:'word',v:s});
  }
  return toks;
}
function parseQuery(q){
  const toks=tokenize(q); let p=0;
  const peek=()=>toks[p]; const next=()=>toks[p++];
  function parseOr(){ let l=parseAnd();
    while(peek()&&peek().t==='or'){ next(); const r=parseAnd(); const a=l,b=r; l=x=>a(x)||b(x); }
    return l; }
  function parseAnd(){ let l=parseNot();
    for(;;){ const tk=peek(); if(!tk) break;
      if(tk.t==='and'){ next(); const r=parseNot(); const a=l,b=r; l=x=>a(x)&&b(x); continue; }
      if(tk.t==='op'||tk.t==='('||tk.t==='not'){ const r=parseNot(); const a=l,b=r; l=x=>a(x)&&b(x); continue; }
      break; }
    return l; }
  function parseNot(){ if(peek()&&peek().t==='not'){ next(); const r=parseNot(); return x=>!r(x); }
    return parsePrimary(); }
  function parsePrimary(){ const tk=peek();
    if(!tk) return ()=>true;
    if(tk.t==='('){ next(); const e=parseOr(); if(peek()&&peek().t===')') next(); return e; }
    if(tk.t==='op'){ next(); return operand(tk); }
    next(); return ()=>true; }
  function operand(tk){ const v=(tk.v||'').toLowerCase();
    if(tk.kind==='tag') return b=> (b.tags||[]).some(t=>t.toLowerCase().includes(v));
    // word / phrase: search across all fields including tags
    return b=> [b.title,b.description,b.note,b.url,(b.tags||[]).join(' ')]
                 .some(f=>(f||'').toLowerCase().includes(v)); }
  const fn=parseOr(); return fn;
}
function matches(b, q){ if(!q||!q.trim()) return true;
  try{ return parseQuery(q)(b); }
  catch(e){ const s=q.toLowerCase();
    return [b.title,b.description,b.note,b.url,(b.tags||[]).join(' ')].some(f=>(f||'').toLowerCase().includes(s)); } }

